const date = new Date().toLocaleDateString('es-BO', { timeZone: 'America/La_Paz' });
const pilares = ['Dolor real (proceso manual que pierde plata/tiempo)','Antes/Despues (sin metricas falsas)','Caso de uso concreto (chatbot / web que capta / automatizacion)','Educativo o mito de IA para pyme','Detras de escena de ONIA','Autoridad Sergio fundador'];
const i = Math.floor(Date.now()/86400000) % pilares.length;
return [{ json: { date, pilarDelDia: pilares[i] } }];

const j = items[0].json || {};
const content = j.content || j.output || j.text || j.response || (j.message && j.message.content) || (j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '';
const NL = String.fromCharCode(10);
const date = new Date().toLocaleDateString('es-BO', { timeZone: 'America/La_Paz' });
const body = typeof content === 'string' ? content : JSON.stringify(content);
const head = 'ONIA | Guiones de contenido ' + date;
const foot = 'Nada se publica sin tu OK. Para producir: Genera Reel ONIA: <tema>.';
const text = body ? (head + NL + NL + body + NL + NL + foot) : (head + NL + 'No se pudo generar. Revisar nodo OpenAI en n8n.');
return [{ json: { text: text.slice(0, 3900) } }];
